<script lang="ts">import { createUploadMd5, createUploadParts, createUploadProgress } from '@fex/components-svelte/primitive/upload'; let { id }: { id: string } = $props(); const md5 = createUploadMd5(() => id); const md5State = md5.state; const parts = createUploadParts(() => id); const progress = createUploadProgress(() => id, { md5Weight: 0.1 }); const statusText = { pending: '等待', uploading: '上传中', success: '完成', error: '失败' } as const; const completed = $derived($parts.filter((part) => part.status === 'success').length)</script>
<div class="mt-space-sm space-y-space-sm text-xs"><div><div class="mb-1 flex justify-between text-muted-foreground"><span>总进度（MD5 10% + 上传 90%）</span><span>{$progress.percent.toFixed(0)}%</span></div><div class="h-1.5 overflow-hidden rounded-full bg-muted"><div class="h-full bg-primary transition-[width]" style:width={`${$progress.percent}%`}></div></div></div>{#if md5.available}<div><div class="mb-1 flex justify-between text-muted-foreground"><span>{$md5State?.status === 'calculating' ? '正在计算 MD5' : $md5State?.status === 'success' ? 'MD5 计算完成' : '准备计算 MD5'}</span><span>{($md5State?.progress ?? 0).toFixed(0)}%</span></div>{#if $md5State?.value}<p class="mt-1 break-all text-muted-foreground">{$md5State.value}</p>{/if}</div>{/if}{#if $parts.length}<div><p class="mb-1 text-muted-foreground">分片进度：{completed}/{$parts.length}</p><div class="grid grid-cols-4 gap-1 sm:grid-cols-8">{#each $parts as part (part.index)}<div class="rounded border border-border px-1 py-0.5 text-center data-[status=error]:border-danger data-[status=error]:text-danger data-[status=success]:border-primary data-[status=success]:text-primary" data-status={part.status} title={`分片 ${part.index + 1}：${statusText[part.status]}`}>{part.index + 1} · {part.status === 'uploading' ? `${part.progress?.percent?.toFixed(0) ?? 0}%` : statusText[part.status]}</div>{/each}</div></div>{/if}</div>
